def apply(root):
    root=Path(root).resolve(); manifest=root/'manifest.json'
    required=[root/'content-scripts/content.js',root/'fix3-policy.js',manifest]
    for p in required:
        if not p.is_file(): raise RuntimeError(f'missing target: {p}')
    base=(root/'content-scripts/content.js').read_text(encoding='utf-8-sig')
    if 'DPP_COMPLETION_GATE_31' not in base: raise RuntimeError('target is not a compatible Fix3.1 tree; no files changed')
    staged={}
    for rel,label,old,new in PATCHES:
        p=root/rel; s=staged.get(p,p.read_text(encoding='utf-8-sig'))
        if new in s and old not in s:
            staged[p]=s; continue
        c=s.count(old)
        if c!=1: raise RuntimeError(f'{label}: expected one old marker, found {c}; no files changed')
        staged[p]=s.replace(old,new,1)
    obj=json.loads(manifest.read_text(encoding='utf-8-sig'))
    obj['version_name']=f"{obj.get('version','unknown')} ShunCode MCP Fix 3.2"
    staged[manifest]=json.dumps(obj,ensure_ascii=False,indent=2)+'\n'
    for rel in ('_locales/en/messages.json','_locales/zh_CN/messages.json'):
        p=root/rel
        if p.is_file():
            o=json.loads(p.read_text(encoding='utf-8-sig'))
            if 'extension_name' in o:o['extension_name']['message']='DeepSeek++ ShunCode MCP Fix 3.2'
            if 'extension_action_title' in o:o['extension_action_title']['message']='DeepSeek++ ShunCode MCP Fix 3.2'
            staged[p]=json.dumps(o,ensure_ascii=False,indent=2)+'\n'
    # Fail-closed: no writes before every marker is validated.
    for p,s in staged.items(): p.write_text(s,encoding='utf-8',newline='')
    print(f'Fix3.2 overlay applied safely to {root}')
if __name__=='__main__':
    if len(sys.argv)!=2: raise SystemExit('usage: apply-fix32.py <fix31-root>')
    apply(sys.argv[1])
